import{_ as s,o as t,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0053 — Les écritures des visiteurs anonymes vivent sous /api/v1/public/, les anciennes adresses restent en alias déprécié","description":"Extrait de docs/adr/0053-ecritures-anonymes-sous-public.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0053 — Les écritures des visiteurs anonymes vivent sous /api/v1/public/, les anciennes adresses restent en alias déprécié","description":"Extrait de docs/adr/0053-ecritures-anonymes-sous-public.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0053-ecritures-anonymes-sous-public.md","filePath":"developpeurs/adr/0053-ecritures-anonymes-sous-public.md"}'),o={name:"developpeurs/adr/0053-ecritures-anonymes-sous-public.md"};function r(a,e,l,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0053--les-écritures-des-visiteurs-anonymes-vivent-sous-apiv1public-les-anciennes-adresses-restent-en-alias-déprécié" tabindex="-1">ADR-0053 — Les écritures des visiteurs anonymes vivent sous <code>/api/v1/public/</code>, les anciennes adresses restent en alias déprécié <a class="header-anchor" href="#adr-0053--les-écritures-des-visiteurs-anonymes-vivent-sous-apiv1public-les-anciennes-adresses-restent-en-alias-déprécié" aria-label="Permalink to &quot;ADR-0053 — Les écritures des visiteurs anonymes vivent sous `/api/v1/public/`, les anciennes adresses restent en alias déprécié {#adr-0053--les-écritures-des-visiteurs-anonymes-vivent-sous-apiv1public-les-anciennes-adresses-restent-en-alias-déprécié}&quot;">​</a></h1><p><strong>Date :</strong> 26 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat SEC-2 (moyen)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Trois écritures de visiteurs anonymes vivaient hors de <code>/api/v1/public/</code> :</p><ul><li>le bandeau de cookies et le consentement (<code>/api/v1/cookies/banner</code>, <code>/cookies/consent</code>, sa relecture et son retrait) ;</li><li>les votes d&#39;utilité sur une fiche ou une page (<code>…/usefulness-vote</code>) ;</li><li>le vote de sondage (<code>…/poll-vote</code>).</li></ul><p>L&#39;audit relève deux défauts.</p><ol><li><strong>Aucune limite de débit.</strong> Chaque consentement écrit une ligne de preuve, et chaque vote incrémente un compteur. Un script pouvait remplir la table des preuves ou fausser un sondage sans rencontrer de limite (ADR-0031).</li><li><strong>Injoignables en production.</strong> Le proxy de la pile (<code>deploy/caddy/sites-disponibles/cms.caddy</code>) n&#39;ouvre au public que <code>/_api/api/v1/public/*</code>. Un site public derrière le profil par défaut ne pouvait ni afficher le bandeau, ni enregistrer un consentement, ni voter.</li></ol><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Les nouvelles adresses sont sous <code>/api/v1/public/</code></strong>, avec le même chemin après ce préfixe : <code>/api/v1/public/cookies/consent</code>, <code>/api/v1/public/listings/{clé}/entries/{id}/usefulness-vote</code>, etc. Même corps, même réponse, même 404 unique.</li><li><strong>Les anciennes adresses restent servies, en alias déprécié</strong>, pour ne casser aucun front qui les appelait déjà en direct (hors du proxy) : <ul><li>elles sont marquées <code>deprecated</code> dans le schéma OpenAPI ;</li><li>chaque réponse porte <code>Deprecation: true</code> et <code>Link: &lt;nouvelle adresse&gt;; rel=&quot;successor-version&quot;</code> (RFC 9745 et RFC 8594) ;</li><li>elles partagent le <strong>même compteur</strong> de limite de débit que leur remplaçante : passer par l&#39;alias ne double pas le seuil.</li></ul></li><li><strong>Deux nouvelles politiques de débit, par adresse</strong> (ADR-0031), réglables et désactivables par variable d&#39;environnement : <ul><li><code>RATE_LIMIT_CONSENT_PER_IP</code>, 30 par 10 minutes, pour l&#39;enregistrement, la relecture et le retrait d&#39;un consentement ;</li><li><code>RATE_LIMIT_VOTE_PER_IP</code>, 60 par 10 minutes, pour les trois votes ensemble.</li></ul></li><li><strong>Toujours ni captcha ni identification du visiteur sur les votes.</strong> La décision déjà assumée par <code>test_le_vote_public_n_exige_aucun_captcha</code> ne change pas : la limite compte l&#39;adresse le temps d&#39;une fenêtre, sous forme d&#39;empreinte, sans rien conserver au-delà (ADR-0031).</li></ol><p>Le retrait des alias n&#39;a pas de date. Il fera l&#39;objet d&#39;une ADR quand les fronts connus auront migré.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Déplacer sans alias</strong></td><td>Cela casse sans prévenir tout front qui appelait l&#39;API en direct.</td></tr><tr><td><strong>Garder les adresses et ajouter la limite seule</strong></td><td>Les routes restent injoignables derrière le proxy de production.</td></tr><tr><td><strong>Ouvrir ces chemins dans Caddy</strong></td><td>Cela élargit la surface publique au cas par cas, alors que la règle « seul <code>/public/</code> est public » tient en une ligne et se vérifie d&#39;un coup d&#39;œil.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le bandeau, le consentement et les votes fonctionnent derrière le proxy de la pile de production.</li><li>Une rafale de consentements ou de votes s&#39;arrête au seuil, avec un 429 et <code>Retry-After</code>.</li></ul><p><strong>Négatives</strong></p><ul><li>Sept routes existent deux fois dans le schéma OpenAPI tant que les alias vivent.</li><li>Une sortie NAT partagée (un lycée, une médiathèque) partage aussi son compteur. Les seuils sont larges pour cette raison.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Nouvelles adresses, alias dépréciés, politiques <code>consent_per_ip</code> et <code>vote_per_ip</code> — <code>app/api/cookies.py</code>, <code>app/api/listings.py</code>, <code>app/api/pages.py</code>, <code>app/core/deprecation.py</code>, <code>app/core/rate_limit.py</code>, <code>app/core/config.py</code>, <code>.env.example</code>, <code>deploy/compose.yml</code> ; tests <code>tests/test_ecritures_anonymes_publiques.py</code>, <code>tests/test_rate_limit.py</code> (<code>test_votes_anonymes_bornes_par_adresse_alias_compris</code>, <code>test_consentement_borne_par_adresse</code>).</li><li>[ ] Retirer les alias dépréciés, par une ADR, quand les fronts connus auront migré.</li></ul>',19)])])}const v=s(o,[["render",r]]);export{m as __pageData,v as default};
